  "city.doppel-parlor.description": "Um salão ao lado do Laboratório Central de Pesquisa de Doppel. Os convidados se sentam e recebem os diários de pesquisa página por página.",
  "city.doppel-lab.description": "O instituto de pesquisa interno, bem no fundo do laboratório de Doppel. Os diários deixados pelos pesquisadores enviados a Eternal se reúnem aqui.",
  "city.doppel-lab.displayName": "Doppel · Instituto de Pesquisa Interno",
  "city.doppel-office.description": "O departamento de administração de Doppel, que reúne os resultados de pesquisa e os usos das relíquias. As aprovações passam por muitas etapas, então a espera é longa.",
  "city.doppel-office.displayName": "Doppel · Departamento de Administração",
  "city.rust-garage.description": "A oficina de manutenção de Rust. Os pedidos para consertar equipamentos de pesquisa quebrados não param de chegar.",
  "city.rust-garage.displayName": "Rust · Oficina de Manutenção",
  "city.rust-lease.description": "O departamento de gestão de aluguel de Rust, que empresta equipamentos de alto desempenho. Até uma única prorrogação puxa longas negociações.",
  "city.rust-lease.displayName": "Rust · Gestão de Aluguel",
  "city.doppel-upper.description": "O andar mais alto do laboratório de Doppel. Aqui se sentam os que decidem o propósito da pesquisa.",
  "city.doppel-upper.displayName": "Doppel · Alta Cúpula",
  "city.rust-works.description": "Uma enorme fundição no coração de Rust. O projeto e o conserto dos equipamentos de pesquisa se reúnem em um só lugar.",
  "city.rust-works.displayName": "Rust · Fundição Central",
  "city.odidi-embassy.description": "A sala de recepção onde Odidi, a cidade que estuda os sonhos, recebe visitantes externos. As propostas sempre partem deles primeiro.",
  "city.odidi-embassy.displayName": "Odidi · Sala de Recepção Diplomática",
  "journal.interaction-doppel-lab-01.title": "Diário da missão que não voltou",
  "journal.interaction-doppel-lab-01.body": "O diário de um pesquisador enviado a Eternal. A última página é uma única linha, \"O substituto chegou\", e a caixa de assinatura abaixo continua vazia.",
  "city.department.exchange": "Casa de câmbio",
  "city.department.council": "Conselho",
  "city.doppel-parlor.displayName": "Doppel · Salão do Laboratório Central de Pesquisa",
