  "shopClerk.protia.name": "Protia",
  "shopClerk.haine.name": "Haine",
  "journal.interaction-doppel-01.title": "A placa do Corredor Azul",
  "journal.interaction-doppel-01.body": "O primeiro quadro de avisos da estufa ainda pede que os corpos restaurados sejam recebidos como novos vizinhos, não como espetáculo.",
  "journal.interaction-doppel-02.title": "A saudação que se repete",
  "bond.torika.0": "Quem é você?",
  "bond.torika.1": "Você voltou.",
  "bond.torika.2": "Pode ficar ao meu lado.",
  "bond.torika.3": "O que vamos fazer hoje?",
  "bond.torika.4": "Conheço seus passos.",
  "bond.torika.5": "Fica tudo calmo quando estamos juntos.",
  "bond.torika.6": "Eu protejo suas costas.",
  "bond.torika.7": "Eu estava esperando.",
  "bond.torika.8": "Me sinto segura quando você vem.",
  "bond.torika.9": "Vou com você até o fim.",
  "bond.torika.10": "Eu mesma vou proteger nosso jardim.",
  "bond.rex.0": "Não me toque.",
  "bond.rex.1": "Não está com medo?",
  "bond.rex.2": "Um pouco interessante.",
  "bond.rex.3": "Venha também na próxima caçada.",
  "bond.rex.4": "Já decorei seu cheiro.",
  "bond.rex.5": "Não saia do meu lado.",
  "bond.rex.6": "O que vier atrás de você, eu mordo.",
  "bond.rex.7": "Atrasado de novo hoje.",
  "bond.rex.8": "Prefiro sua voz a ordens.",
  "bond.rex.9": "Você é minha única matilha.",
  "bond.rex.10": "Estarei do seu lado para sempre.",
  "bond.spino.0": "…O que foi?",
  "bond.spino.1": "Sinto falta da água.",
  "bond.spino.2": "Tudo bem ficar em silêncio.",
  "bond.spino.3": "Me conta mais de você.",
  "bond.spino.4": "As ondas estão calmas hoje.",
  "bond.spino.5": "Gosto de caminhar junto.",
  "bond.spino.6": "Se for perigoso, fique atrás de mim.",
  "bond.spino.7": "Eu sabia que você viria.",
  "bond.spino.8": "Já me acostumei com esta cidade.",
  "bond.spino.9": "Ao seu lado é a minha água.",
  "bond.spino.10": "Vamos fluir juntos para qualquer lugar.",
  "bond.generic.0": "Ainda é um pouco estranho.",
  "bond.generic.1": "Nos encontramos de novo hoje.",
  "bond.generic.2": "Estou me acostumando aos poucos.",
  "bond.generic.3": "Vamos juntos em uma missão.",
  "bond.generic.4": "Fico feliz quando você vem.",
  "bond.generic.5": "Pode ficar ao meu lado.",
  "bond.generic.6": "Desta vez também vou ajudar.",
  "bond.generic.7": "Eu estava esperando.",
  "bond.generic.8": "Somos bons companheiros.",
  "bond.generic.9": "Quero ficar junto por muito tempo.",
  "bond.generic.10": "De agora em diante conto com você.",
