  "relic.quetzalcoatlus.excavationSite": "Depósitos fluviais do Cretáceo Superior, Big Bend, Texas, EUA",
  "relic.quetzalcoatlus.fossilRecord": "De uma camada de argilito à beira de um rio foi recuperada uma fileira de vértebras cervicais ocas ainda unidas. As paredes ósseas, finas como papel, são interpretadas como uma adaptação para manter o corpo no ar, e registrou-se também uma superfície sedimentar com marcas apenas de pontas de asa.",
  "relic.quetzalcoatlus.catalogSummary": "Grande espécime baseado em Quetzalcoatlus, com pescoço e membrana alar restaurados em excesso.",
  "relic.quetzalcoatlus.unlockRecord": "Registro de desastre 006. Apareceu no céu sobre a margem de um rio. Usava uma capa preta aberta como asas e um chapéu pontudo de aba larga, e enfeites em forma de ponta de flecha balançavam nas correntes. Ficou olhando de cima por um bom tempo e depois mergulhou num único golpe; um bater de asas bastou para varrer o equipamento próximo. Não foi confirmado de onde veio nem o que procurava.",
  "relic.quetzalcoatlus.observation.originYear": "Há cerca de 68 milhões de anos",
  "relic.quetzalcoatlus.observation.restorationYear": "E.C. 18",
  "relic.quetzalcoatlus.observation.lifeStage": "Adulta",
  "relic.quetzalcoatlus.observation.height": "2,15 m",
  "relic.quetzalcoatlus.observation.weight": "92 kg",
  "relic.quetzalcoatlus.passive.desc": "Ao abrir a batalha, mergulha sobre o alvo e o atordoa, e aumenta a chance de crítico.",
  "relic.quetzalcoatlus.passive.name": "Caça em mergulho",
  "relic.quetzalcoatlus.ferocity.name": "Bater de asas da tempestade",
