  "observation.torika-frightened-shield.torika-shield-admit.tag": "Admitir o medo",
  "observation.torika-frightened-shield.torika-shield-protect.label": "Firma as pernas trêmulas e bloqueia o caminho",
  "observation.torika-frightened-shield.torika-shield-protect.tag": "Instinto protetor",
  "observation.rex-size-rivalry.prompt": "Como ela reage quando alguém bem maior bloqueia o caminho?",
  "observation.rex-size-rivalry.rex-size-formal.label": "Endireita-se e propõe formalmente um duelo primeiro",
  "observation.rex-size-rivalry.rex-size-formal.tag": "Rivalidade formal",
