  "observation.rex-size-rivalry.rex-size-wrestle.tag": "Rivalidade física",
  "observation.rex-strong-challenge.prompt": "O que você fará ao encontrar um oponente esmagadoramente forte?",
  "observation.rex-strong-challenge.rex-strong-fair.label": "Estudar os pontos fortes e depois competir de igual para igual",
  "observation.rex-strong-challenge.rex-strong-fair.tag": "Desafio justo",
  "observation.rex-strong-challenge.rex-strong-eager.label": "Com os olhos brilhando, quer decidir na hora quem é mais forte",
  "observation.rex-strong-challenge.rex-strong-eager.tag": "Atraída pela força",
  "observation.rex-small-etiquette.prompt": "E se uma Relíquia pequena errar nas boas maneiras sem querer?",
  "observation.rex-small-etiquette.rex-small-guide.label": "Abaixa-se primeiro e ensina devagar o cumprimento certo",
  "observation.rex-small-etiquette.rex-small-guide.tag": "Orientação gentil",
  "observation.rex-small-etiquette.rex-small-example.label": "Cumprimenta com educação primeiro e espera que imitem",
  "observation.rex-small-etiquette.rex-small-example.tag": "Dar o exemplo",
  "observation.spino-night-alarm.prompt": "E se, numa patrulha noturna, um alarme do tanque e um chamado de resgate de outra zona chegarem juntos?",
  "observation.spino-night-alarm.spino-alarm-rescue.label": "Informa brevemente o local do resgate e vai direto para lá",
  "observation.spino-night-alarm.spino-alarm-rescue.tag": "Missão em primeiro lugar",
  "observation.spino-night-alarm.spino-alarm-command.label": "Deixa a checagem do tanque com o guarda mais próximo e libera a rota de resgate",
  "observation.spino-night-alarm.spino-alarm-command.tag": "Comando calmo",
  "observation.spino-aquarium-decoration.prompt": "E se quem pesquisa notar um enfeite novo no aquário?",
  "observation.spino-aquarium-decoration.spino-decoration-deny.label": "Diz que sempre esteve ali, desvia o olhar e só ajeita o ângulo",
  "observation.spino-aquarium-decoration.spino-decoration-deny.tag": "Péssima em disfarçar",
  "observation.spino-aquarium-decoration.spino-decoration-shelter.label": "Explica brevemente que os peixes precisavam de um esconderijo",
  "observation.spino-aquarium-decoration.spino-decoration-shelter.tag": "Gentileza escondida",
  "observation.spino-aquarium-cleaning.prompt": "E se quem pesquisa se oferecer para ajudar na limpeza do aquário, que não conhece?",
  "observation.spino-aquarium-cleaning.spino-cleaning-gloves.label": "Começa a recusar e depois entrega em silêncio um par de luvas reserva",
  "observation.spino-aquarium-cleaning.spino-cleaning-gloves.tag": "Confiança silenciosa",
  "observation.spino-aquarium-cleaning.spino-cleaning-roles.label": "Fica com as plantas aquáticas e divide as tarefas com precisão",
  "observation.spino-aquarium-cleaning.spino-cleaning-roles.tag": "Consideração prática",
  "observation.luka-sofa-conversation.prompt": "Como Luka reage quando quem pesquisa fala com ele no sofá do laboratório?",
  "observation.luka-sofa-conversation.luka-sofa-silence.label": "Abre espaço e curte um silêncio confortável lado a lado",
  "observation.luka-sofa-conversation.luka-sofa-silence.tag": "Proximidade tranquila",
  "observation.luka-sofa-conversation.luka-sofa-chat.label": "Deitado no sofá, não para de puxar assuntos novos",
  "observation.luka-sofa-conversation.luka-sofa-chat.tag": "Simpatia tagarela",
  "observation.luka-sprint-rival.prompt": "Como ele corre quando se alinha com outra Relíquia carnívora?",
  "observation.luka-sprint-rival.luka-sprint-compete.label": "Dá tudo pelo recorde assim que o sinal soa",
  "observation.luka-sprint-rival.luka-sprint-compete.tag": "Rivalidade direta",
  "observation.luka-sprint-rival.luka-sprint-pace.label": "Observa a passada do corredor ao lado e vão juntos à linha",
  "observation.luka-sprint-rival.luka-sprint-pace.tag": "Acompanhar o ritmo do outro",
  "observation.luka-cheesecake-weight.prompt": "O que você faz quando Luka começa a se preocupar com o peso depois do cheesecake?",
