  "relic.raitia-grass.origin": "Arganaz",
  "relic.raitia-grass.excavationSite": "Sedimento de caverna cárstica, Eslovênia",
  "relic.raitia-grass.fossilRecord": "De uma única camada de sedimento da caverna foram recuperados dezenas de crânios da mesma espécie. Cinco deles coincidem tanto em tamanho e dentição que foram classificados como uma só ninhada.",
  "relic.raitia-grass.catalogSummary": "Espécime baseado em arganaz, restaurado com incisivos e bolsas nas bochechas enormes.",
  "relic.raitia-grass.squadNote": "A massa descartável da Aniquilação. Fluem todas de uma vez para onde forem apontadas e enchem o corredor; as de trás pisam direto onde as da frente caíram.",
  "relic.raitia-grass.researcherTitle": "Pesquisador",
  "relic.raitia-grass.unlockRecord": "Registro de identificação 207. Confirmado como pertencente à Aniquilação. Entre as cinco de pijama com capuz e orelhas de rato, esta usa um laço verde; chamam atenção a bolsinha em forma de queijo, os chinelos com dentes e a cauda listrada com uma fita na ponta. Ao achar comida, avisou não com um guincho, mas com o som dos incisivos, e as irmãs que ouviram correram em bando para o mesmo lugar ao mesmo tempo. Onde roía ficavam brotos novos espalhados, e em cada pegada do caminho brotaram sementes, deixando uma trilha verde. Não foi confirmado por que ela não para de comer nem quando chega a estação de hibernar.",
  "relic.raitia-grass.observation.originYear": "Há cerca de 2 milhões de anos",
  "relic.raitia-grass.observation.restorationYear": "E.C. 2",
  "relic.raitia-grass.observation.lifeStage": "Juvenil",
  "relic.raitia-grass.observation.height": "0,94 m",
  "relic.raitia-grass.observation.weight": "21 kg",
  "relic.raitia-grass.passive.name": "Hibernação",
  "relic.raitia-grass.passive.desc": "Uma vez por batalha, quando o PV cai à metade ou menos, recupera 3% do PV máximo a cada segundo por 5 segundos.",
  "relic.raitia-grass.ferocity.name": "Comilança",
  "relic.raitia-grass.basic.name": "Roída de incisivos",
  "relic.raitia-grass.ultimate.name": "Despejo das bochechas",
  "relic.raitia-grass.projectName": "ANNIHILATION SWARM — População superalimentada",
  "relic.raitia-water.name": "Guttia",
  "relic.raitia-water.origin": "Arganaz",
  "relic.raitia-water.excavationSite": "Sedimento de caverna cárstica, Eslovênia",
  "relic.raitia-water.fossilRecord": "De uma única camada de sedimento da caverna foram recuperados dezenas de crânios da mesma espécie. Cinco deles coincidem tanto em tamanho e dentição que foram classificados como uma só ninhada.",
  "relic.raitia-water.catalogSummary": "Espécime baseado em arganaz, restaurado com incisivos e bolsas nas bochechas enormes.",
  "relic.raitia-water.squadNote": "A massa descartável da Aniquilação. Fluem todas de uma vez para onde forem apontadas e enchem o corredor; as de trás pisam direto onde as da frente caíram.",
  "relic.raitia-water.researcherTitle": "Pesquisador",
  "relic.raitia-water.unlockRecord": "Registro de identificação 208. Confirmado como pertencente à Aniquilação. Entre as do mesmo pijama com capuz, esta tem a cauda listrada de azul com um tufo de algodão na ponta, e sorri com uma mão na cintura e os dedos da outra no canto da boca. Ao ouvir o som dos incisivos de uma irmã, saiu correndo primeiro, sorrindo, e ao se aproximar roeu com os incisivos o equipamento que estava ao alcance da mão. Onde o bando passou, ficou uma longa fileira de pegadas molhadas. Não foi confirmado o que molha essas pegadas.",
  "relic.raitia-water.observation.originYear": "Há cerca de 2 milhões de anos",
  "relic.raitia-water.observation.restorationYear": "E.C. 2",
  "relic.raitia-water.observation.lifeStage": "Juvenil",
  "relic.raitia-water.observation.height": "0,94 m",
  "relic.raitia-water.observation.weight": "21 kg",
  "relic.raitia-water.passive.name": "Hibernação",
  "relic.raitia-water.passive.desc": "Uma vez por batalha, quando o PV cai à metade ou menos, recupera 3% do PV máximo a cada segundo por 5 segundos.",
  "relic.raitia-water.ferocity.name": "Comilança",
  "relic.raitia-water.basic.name": "Roída de incisivos",
