  "relic.raitia-fire.name": "Favia",
  "relic.raitia-fire.origin": "Arganaz",
  "relic.raitia-fire.excavationSite": "Sedimento de caverna cárstica, Eslovênia",
  "relic.raitia-fire.fossilRecord": "De uma única camada de sedimento da caverna foram recuperados dezenas de crânios da mesma espécie. Cinco deles coincidem tanto em tamanho e dentição que foram classificados como uma só ninhada.",
  "relic.raitia-fire.catalogSummary": "Espécime baseado em arganaz, restaurado com incisivos e bolsas nas bochechas enormes.",
  "relic.raitia-fire.squadNote": "A massa descartável da Aniquilação. Fluem todas de uma vez para onde forem apontadas e enchem o corredor; as de trás pisam direto onde as da frente caíram.",
  "relic.raitia-fire.researcherTitle": "Pesquisador",
  "relic.raitia-fire.unlockRecord": "Registro de identificação 209. Confirmado como pertencente à Aniquilação. Entre as do mesmo pijama com capuz, esta usa uma fita xadrez rosa e fica de pé com cara de quem não acordou direito, uma mão esfregando os olhos e a outra na cintura. Embora parecesse sonolenta, não parou de comer e continuou roendo com os incisivos mesmo com as bochechas cheias. Quando as irmãs correram em bando, seguiu atrás, esfregando os olhos. Não foi confirmado se o sono é fingido ou real.",
  "relic.raitia-fire.observation.originYear": "Há cerca de 2 milhões de anos",
  "relic.raitia-fire.observation.restorationYear": "E.C. 2",
  "relic.raitia-fire.observation.lifeStage": "Juvenil",
  "relic.raitia-fire.observation.height": "0,94 m",
  "relic.raitia-fire.observation.weight": "21 kg",
  "relic.raitia-fire.passive.name": "Hibernação",
  "relic.raitia-fire.passive.desc": "Uma vez por batalha, quando o PV cai à metade ou menos, recupera 3% do PV máximo a cada segundo por 5 segundos.",
  "relic.raitia-fire.ferocity.name": "Comilança",
  "relic.raitia-fire.basic.name": "Roída de incisivos",
  "relic.raitia-fire.ultimate.name": "Despejo das bochechas",
