  "relic.raitia-earth.name": "Silia",
  "relic.raitia-earth.origin": "Arganaz",
  "relic.raitia-earth.excavationSite": "Sedimento de caverna cárstica, Eslovênia",
  "relic.raitia-earth.fossilRecord": "De uma única camada de sedimento da caverna foram recuperados dezenas de crânios da mesma espécie. Cinco deles coincidem tanto em tamanho e dentição que foram classificados como uma só ninhada.",
  "relic.raitia-earth.catalogSummary": "Espécime baseado em arganaz, restaurado com incisivos e bolsas nas bochechas enormes.",
  "relic.raitia-earth.squadNote": "A massa descartável da Aniquilação. Fluem todas de uma vez para onde forem apontadas e enchem o corredor; as de trás pisam direto onde as da frente caíram.",
  "relic.raitia-earth.researcherTitle": "Pesquisador",
  "relic.raitia-earth.unlockRecord": "Registro de identificação 210. Confirmado como pertencente à Aniquilação. Entre as do mesmo pijama com capuz, esta se destaca pela base marrom, o laço amarelo e a trança, e leva um grande tufo de pelos na ponta da cauda. Quando ficou de pé com as mãos estendidas à frente, as irmãs fluíram todas ao mesmo tempo na direção das pontas dos dedos, e onde a da frente caiu, a de trás passou por cima sem parar. Não foi confirmado quem decide a direção para onde apontam seus dedos.",
  "relic.raitia-earth.observation.originYear": "Há cerca de 2 milhões de anos",
  "relic.raitia-earth.observation.restorationYear": "E.C. 2",
  "relic.raitia-earth.observation.lifeStage": "Juvenil",
  "relic.raitia-earth.observation.height": "0,94 m",
  "relic.raitia-earth.observation.weight": "21 kg",
  "relic.raitia-earth.passive.name": "Hibernação",
  "relic.raitia-earth.passive.desc": "Uma vez por batalha, quando o PV cai à metade ou menos, recupera 3% do PV máximo a cada segundo por 5 segundos.",
  "relic.raitia-earth.ferocity.name": "Comilança",
  "relic.raitia-earth.basic.name": "Roída de incisivos",
  "relic.raitia-earth.ultimate.name": "Despejo das bochechas",
