  "relic.raitia-wind.name": "Ventia",
  "relic.raitia-wind.origin": "Arganaz",
  "relic.raitia-wind.excavationSite": "Sedimento de caverna cárstica, Eslovênia",
  "relic.raitia-wind.fossilRecord": "De uma única camada de sedimento da caverna foram recuperados dezenas de crânios da mesma espécie. Cinco deles coincidem tanto em tamanho e dentição que foram classificados como uma só ninhada.",
  "relic.raitia-wind.catalogSummary": "Espécime baseado em arganaz, restaurado com incisivos e bolsas nas bochechas enormes.",
  "relic.raitia-wind.squadNote": "A massa descartável da Aniquilação. Fluem todas de uma vez para onde forem apontadas e enchem o corredor; as de trás pisam direto onde as da frente caíram.",
  "relic.raitia-wind.researcherTitle": "Pesquisador",
  "relic.raitia-wind.unlockRecord": "Registro de identificação 211. Confirmada como pertencente à Aniquilação. É a que usa um laço cor de menta entre as irmãs com o mesmo pijama de capuz; fica de braços cruzados e boca bem fechada. Só seguiu, a contragosto, depois que as irmãs já tinham corrido até a comida, e ao chegar foi a que mais tempo mexeu os incisivos. Nunca foi observada avisando algo com o som dos incisivos.",
  "relic.raitia-wind.observation.originYear": "Há cerca de 2 milhões de anos",
